%% VALIDATE PAPER REPLICATION OUTPUTS
% Performs structural and numerical checks on the outputs generated by
% run_paper_replication.m.
%
% Missing files/variables are treated as errors. Numerical benchmark
% deviations are reported as warnings because small differences can arise
% across MATLAB versions and numerical libraries.

scriptPath = ...
    mfilename('fullpath');

repoFolder = ...
    fileparts(scriptPath);

resultsFolder = ...
    fullfile(repoFolder, 'Results Paper');


%% ------------------------------------------------------------------------
% 1. REQUIRED OUTPUT FILES
% -------------------------------------------------------------------------

requiredFiles = { ...
    'results_nuts3_base2024_target2030_expCase1_capacity.mat'; ...
    'results_nuts3_base2024_target2035_expCase1_capacity.mat'; ...
    'results_nuts3_base2024_target2040_expCase1_capacity.mat'; ...
    'results_nuts3_base2024_target2040_expCase3_capacity.mat'; ...
    'results_nuts3_base2024_target2040_expCase4_capacity.mat'; ...
    'results_nuts3_base2024_target2040_expCase1_capacity_no_reference_yield.mat'; ...
    'Results_scaling_capacity_based.mat'; ...
    'Results_scaling_energy_based.mat'; ...
    'Table_2_nested_logit_estimates.csv'; ...
    'Table_2_nested_logit_estimates.mat'; ...
    'Figure_2_spatial_deployment.pdf'; ...
    'Figure_3_turbine_types.pdf'; ...
    'Figure_4_allocation_comparison.pdf'; ...
    'Figure_4_allocation_comparison_data.csv'; ...
    'Figure_4_allocation_comparison_data.mat'; ...
    'Figure_5_reference_yield_correction_factors.pdf'; ...
    'Figure_6_reference_yield_difference.pdf'; ...
    'Figure_7_reference_yield_scaling.pdf'; ...
    'Figure_9_producer_surplus_comparison.pdf' ...
    };

missingFiles = ...
    strings(0, 1);

for iFile = 1:numel(requiredFiles)

    filePath = ...
        fullfile( ...
            resultsFolder, ...
            requiredFiles{iFile});

    if ~isfile(filePath)

        missingFiles(end + 1, 1) = ...
            string(requiredFiles{iFile}); %#ok<SAGROW>
    end
end

if ~isempty(missingFiles)

    error( ...
        'Replication is missing required output files:\n%s', ...
        strjoin(missingFiles, newline));
end


%% ------------------------------------------------------------------------
% 2. LOAD REFERENCE-YIELD SENSITIVITY RESULTS
% -------------------------------------------------------------------------

capacityData = ...
    load( ...
        fullfile( ...
            resultsFolder, ...
            'Results_scaling_capacity_based.mat'), ...
        'resultsScaling', ...
        'maximumSyntheticNetBenefit', ...
        'baselineDiagnostics');

energyData = ...
    load( ...
        fullfile( ...
            resultsFolder, ...
            'Results_scaling_energy_based.mat'), ...
        'resultsScaling', ...
        'maximumSyntheticNetBenefit');

T_capacity = ...
    capacityData.resultsScaling;

T_energy = ...
    energyData.resultsScaling;

requiredVariables = [ ...
    "scaleRefYield", ...
    "installedCapacity_GW", ...
    "annualGeneration_TWh", ...
    "requiredRemuneration_ctperkWh", ...
    "productionWeightedRemuneration_ctperkWh", ...
    "subsidyExpenditure_bnEUR", ...
    "avoidedGasAndCO2Costs_bnEUR", ...
    "producerSurplusProbabilityBased_bnEUR", ...
    "probabilityBasedSyntheticNetBenefit_bnEUR", ...
    "producerSurplusNpvBased_bnEUR", ...
    "resourceCostBasedNetWelfare_bnEUR", ...
    "capacityNorth_GW", ...
    "capacityNeutral_GW", ...
    "capacitySouth_GW" ...
    ];

assertRequiredVariables( ...
    T_capacity, ...
    requiredVariables, ...
    'capacity-based results');

assertRequiredVariables( ...
    T_energy, ...
    requiredVariables, ...
    'energy-based results');


%% ------------------------------------------------------------------------
% 3. CHECK SCALE GRID AND FINITE VALUES
% -------------------------------------------------------------------------

expectedScaleGrid = ...
    (0:0.005:1.7)';

if height(T_capacity) ~= numel(expectedScaleGrid) || ...
        max(abs(T_capacity.scaleRefYield - expectedScaleGrid)) > 1e-12

    error('Capacity-based reference-yield scale grid is inconsistent.');
end

if height(T_energy) ~= numel(expectedScaleGrid) || ...
        max(abs(T_energy.scaleRefYield - expectedScaleGrid)) > 1e-12

    error('Energy-based reference-yield scale grid is inconsistent.');
end

numericCapacity = ...
    T_capacity{:, requiredVariables(2:end)};

numericEnergy = ...
    T_energy{:, requiredVariables(2:end)};

if any(~isfinite(numericCapacity), 'all')

    error('Capacity-based results contain non-finite paper output values.');
end

if any(~isfinite(numericEnergy), 'all')

    error('Energy-based results contain non-finite paper output values.');
end


%% ------------------------------------------------------------------------
% 4. CURRENT-POLICY CONSISTENCY AT s = 1
% -------------------------------------------------------------------------

idxCapacityS1 = ...
    find( ...
        abs(T_capacity.scaleRefYield - 1) < 1e-12, ...
        1, ...
        'first');

idxEnergyS1 = ...
    find( ...
        abs(T_energy.scaleRefYield - 1) < 1e-12, ...
        1, ...
        'first');

if isempty(idxCapacityS1) || isempty(idxEnergyS1)

    error('The s = 1 current-policy result is missing.');
end

s1Checks = ...
    table( ...
        [ ...
            T_capacity.installedCapacity_GW(idxCapacityS1); ...
            T_capacity.annualGeneration_TWh(idxCapacityS1); ...
            T_capacity.requiredRemuneration_ctperkWh(idxCapacityS1); ...
            T_capacity.productionWeightedRemuneration_ctperkWh(idxCapacityS1) ...
        ], ...
        [ ...
            T_energy.installedCapacity_GW(idxEnergyS1); ...
            T_energy.annualGeneration_TWh(idxEnergyS1); ...
            T_energy.requiredRemuneration_ctperkWh(idxEnergyS1); ...
            T_energy.productionWeightedRemuneration_ctperkWh(idxEnergyS1) ...
        ], ...
        [0.25; 0.25; 0.05; 0.05], ...
        'VariableNames', { ...
            'CapacityTarget', ...
            'EnergyTarget', ...
            'Tolerance'}, ...
        'RowNames', { ...
            'Installed capacity [GW]', ...
            'Annual generation [TWh/year]', ...
            'Base remuneration [ct/kWh]', ...
            'Effective remuneration [ct/kWh]'});

s1Checks.AbsoluteDifference = ...
    abs( ...
        s1Checks.CapacityTarget - ...
        s1Checks.EnergyTarget);

s1Checks.Pass = ...
    s1Checks.AbsoluteDifference <= ...
    s1Checks.Tolerance;

if any(~s1Checks.Pass)

    warning( ...
        'Capacity- and energy-target runs differ more than expected at s = 1.');
end


%% ------------------------------------------------------------------------
% 5. SYNTHETIC NET-BENEFIT MAXIMA
% -------------------------------------------------------------------------

[maxCapacityNB, idxCapacityMax] = ...
    max( ...
        T_capacity.probabilityBasedSyntheticNetBenefit_bnEUR);

[maxEnergyNB, idxEnergyMax] = ...
    max( ...
        T_energy.probabilityBasedSyntheticNetBenefit_bnEUR);

capacityMaximum = ...
    [ ...
        T_capacity.scaleRefYield(idxCapacityMax), ...
        maxCapacityNB ...
    ];

energyMaximum = ...
    [ ...
        T_energy.scaleRefYield(idxEnergyMax), ...
        maxEnergyNB ...
    ];

% Benchmarks from the final model implementation used during code cleanup.
% These are diagnostic reference values, not hard-coded model outputs.
expectedCapacityMaximum = ...
    [0.450, 0.70843];

expectedEnergyMaximum = ...
    [0.265, 1.2238];

maximumTolerance = ...
    [0.010, 0.050];

if any(abs(capacityMaximum - expectedCapacityMaximum) > maximumTolerance)

    warning([ ...
        'Capacity-based synthetic-net-benefit maximum differs from ', ...
        'the reference benchmark.']);
end

if any(abs(energyMaximum - expectedEnergyMaximum) > maximumTolerance)

    warning([ ...
        'Energy-based synthetic-net-benefit maximum differs from ', ...
        'the reference benchmark.']);
end


%% ------------------------------------------------------------------------
% 6. TABLE 2 ESTIMATION OUTPUT
% -------------------------------------------------------------------------

table2Data = ...
    load( ...
        fullfile( ...
            resultsFolder, ...
            'Table_2_nested_logit_estimates.mat'), ...
        'table2Results', ...
        'nrDecisionMaker');

table2Results = ...
    table2Data.table2Results;

if height(table2Results) ~= 11

    error([ ...
        'Table 2 should contain 10 estimated parameters plus ', ...
        'the pseudo-R2 row.']);
end

parameterRows = ...
    1:10;

if any(~isfinite(table2Results.Estimate(parameterRows))) || ...
        any(~isfinite(table2Results.StdError(parameterRows)))

    error('Table 2 contains invalid parameter estimates or standard errors.');
end

expectedParameterNames = [ ...
    "beta1"; ...
    "gamma"; ...
    "lambda"; ...
    "alpha1"; ...
    "alpha2"; ...
    "alpha3"; ...
    "alpha5"; ...
    "alpha6"; ...
    "alpha7"; ...
    "alpha8" ...
    ];

if any(string(table2Results.Parameter(parameterRows)) ~= expectedParameterNames)

    error('Unexpected parameter ordering in Table 2.');
end

pseudoR2 = ...
    table2Results.Estimate(end);

if abs(pseudoR2 - 0.159) > 0.01

    warning( ...
        'Pseudo-R2 differs materially from the reference estimate.');
end


%% ------------------------------------------------------------------------
% 7. FIGURE-9 DIAGNOSTICS
% -------------------------------------------------------------------------

if ~isfield(capacityData, 'baselineDiagnostics') || ...
        isempty(fieldnames(capacityData.baselineDiagnostics))

    error('Capacity-based result file is missing Figure-9 diagnostics.');
end

requiredDiagnosticFields = { ...
    'effectiveRemunerationGrid', ...
    'normalizedSupply', ...
    'finalEffectiveRemuneration', ...
    'normalizedNpvSurplusHeight', ...
    'producerSurplusNpvBased', ...
    'producerSurplusProbabilityBased'};

for iField = 1:numel(requiredDiagnosticFields)

    if ~isfield( ...
            capacityData.baselineDiagnostics, ...
            requiredDiagnosticFields{iField})

        error( ...
            'Figure-9 diagnostics are missing field "%s".', ...
            requiredDiagnosticFields{iField});
    end
end


%% ------------------------------------------------------------------------
% 8. REPORT
% -------------------------------------------------------------------------

fprintf('\n');
fprintf('============================================================\n');
fprintf('PAPER REPLICATION VALIDATION\n');
fprintf('============================================================\n\n');

fprintf('All required output files are present.\n');
fprintf('Reference-yield scale grids are complete and finite.\n\n');

fprintf('Current-policy consistency at s = 1:\n');
disp(s1Checks);

fprintf('Synthetic net-benefit maxima:\n');

maximumSummary = ...
    table( ...
        ["Capacity"; "Energy"], ...
        [capacityMaximum(1); energyMaximum(1)], ...
        [capacityMaximum(2); energyMaximum(2)], ...
        'VariableNames', { ...
            'Target', ...
            'ScaleRefYield', ...
            'SyntheticNetBenefit_bnEUR'});

disp(maximumSummary);

fprintf( ...
    'Table 2 pseudo-R2: %.4f\n', ...
    pseudoR2);

fprintf( ...
    'Table 2 NUTS3 decision makers: %d\n', ...
    table2Data.nrDecisionMaker);

fprintf('\n');
fprintf('Replication validation completed successfully.\n');
fprintf('============================================================\n');


%% ========================================================================
% LOCAL FUNCTION
% ========================================================================

function assertRequiredVariables(T, requiredVariables, label)

    missingVariables = ...
        requiredVariables( ...
            ~ismember( ...
                requiredVariables, ...
                string(T.Properties.VariableNames)));

    if ~isempty(missingVariables)

        error( ...
            '%s are missing variables: %s', ...
            label, ...
            strjoin(missingVariables, ', '));
    end
end
